/**
 * Mark a listing fulfilled. Only the owner may do this, and only while the
 * listing is still active; terminal statuses are never overwritten.
 */
export function fulfillListing(id: number): ListingRow | undefined {
  return setStatus(id, 'fulfilled');
}

/**
 * Soft-delete a listing. Only the owner or an admin may do this, and only
 * while the listing is still active; terminal statuses are never overwritten.
 */
export function softDeleteListing(id: number): ListingRow | undefined {
  return setStatus(id, 'deleted');
}

function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();
  db.update(listings)
    .set({ status, updatedAt: now() })
    .where(and(eq(listings.id, id), eq(listings.status, 'active')))
    .run();
  return getListingById(id);
}

