describe('terminal status guard', () => {
  it('does not resurrect a deleted listing when it is later fulfilled', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });

    const deleted = softDeleteListing(listing.id);
    expect(deleted?.status).toBe('deleted');

    // A second, conflicting terminal transition must be a no-op, not a resurrection.
    const afterFulfill = fulfillListing(listing.id);
    expect(afterFulfill?.status).toBe('deleted');
  });

  it('does not resurrect a fulfilled listing when it is later deleted', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });

    const fulfilled = fulfillListing(listing.id);
    expect(fulfilled?.status).toBe('fulfilled');

    const afterDelete = softDeleteListing(listing.id);
    expect(afterDelete?.status).toBe('fulfilled');
  });

  it('does not transition an expired listing', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    getDb().update(listings).set({ status: 'expired' }).where(eq(listings.id, listing.id)).run();

    expect(fulfillListing(listing.id)?.status).toBe('expired');
    expect(softDeleteListing(listing.id)?.status).toBe('expired');
  });

  it('still fulfills a genuinely active listing', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });

    const fulfilled = fulfillListing(listing.id);
    expect(fulfilled?.status).toBe('fulfilled');
    expect(fulfilled?.updatedAt).toBeGreaterThanOrEqual(listing.updatedAt);
  });

  it('still soft-deletes a genuinely active listing', () => {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });

    const deleted = softDeleteListing(listing.id);
    expect(deleted?.status).toBe('deleted');
    expect(deleted?.updatedAt).toBeGreaterThanOrEqual(listing.updatedAt);
  });
});

